"""Build a readable offline reference from actual checked detail rows."""
from pathlib import Path
import json,html,re
ROOT=Path(__file__).resolve().parents[1];D=ROOT/'docs/launch-data'
def clean(s):
    s=re.sub(r'\|c[0-9a-fA-F]{8}|\|r','',s)
    return re.sub(r'\|H[^|]*\|h(.*?)\|h',r'\1',s)
rows=json.loads((D/'functional-tests.json').read_text())['results']
cards=''.join('<article><h2>'+html.escape(r['profession']+' / '+str(r.get('spell',r.get('item'))))+'</h2><pre>'+html.escape(clean(r['renderedRows']))+'</pre></article>' for r in rows if 'renderedRows' in r)
page='''<!doctype html><meta charset="utf-8"><title>ProfPaden launch data checks</title><style>body{background:#101921;color:#e5edf3;font:16px/1.6 system-ui;margin:0}main{max-width:1000px;margin:auto;padding:40px 25px}h1{font-size:34px}article,.stats{padding:22px;margin:20px 0;background:#1b2a35;border:1px solid #344958;border-radius:10px}pre{white-space:pre-wrap;font:inherit}a{color:#8bd5ff}small{color:#b8cad7}.stats{display:flex;gap:40px;flex-wrap:wrap}.stats b{font-size:30px;color:#9de1c2;display:block}img{max-width:100%}</style><main><small>OFFLINE FUNCTIONAL REFERENCE / 0.20.32-rc1</small><h1>Newer profession item sources</h1><p>Actual addon detail rows generated by Lua 5.1 tests. These text cards are an offline reference, not game screenshots.</p><div class="stats"><span><b>966</b>items checked</span><span><b>389</b>with published relationships</span><span><b>503</b>new item acquisitions</span><span><b>17</b>offline checks passed</span></div><p>All 54 newer materials remain browsable. The 577 items with no additional relationships retain prior data. Unknown locations remain unknown.</p><h2>Simulator evidence</h2><p>UIForever build 1.60.1.70450 / interface 16001. No Lua errors or missing APIs were listed after the checked states. Its existing map-texture limitation remains.</p><img src="simulator-blueprint.png" alt="UIForever blueprint requirements and no Lua errors"><p><a href="README.md">Coverage, provenance and limitations</a></p>'''+cards+'</main>'
(D/'preview.html').write_text(page,encoding='utf8')
print('Updated offline reference')
